from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferMissingArguments


class AndroidDataTransferHttp(LteDataTransfer):
    """Object responsible for managing Android data transfer."""
    # pylint: disable = protected-access, duplicate-code

    def __init__(self, name, dt_definition, configuration, ue_instance, logger_name='ute_ue'):
        """

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param ue_instance:
        """
        super().__init__(name, dt_definition, configuration, logger_name)
        self.ue_instance = ue_instance
        self.success_started = False
        self.is_running_ = False
        try:
            self.url = self._dt_definition.protocol_details['url']
        except KeyError:
            raise DataTransferMissingArguments("Please provide 'url' parameter if you use http protocol.")
        self.logger.debug(f"{self.name} created with configuration: url={self.url}")

    def start(self):
        """
        Starts data transfer with 'url' parameter if defined in dt_definition passed during initialization.

        :return: None
        :raises: :py:class:`ute_ue.exceptions.DataTransferIllegalArguments`: If 'url' parameter has not been provided
        """
        self.is_running_ = True
        self.logger.info(f'{self.name}: Triggering HTTP request on the UE {self.ue_instance.ue_id} '
                         f'using url {self.url}.')
        self.ue_instance.rpc_client.start_data_transfer(
            ue_id=self.ue_instance.ue_id, data_transfer_id=self.name,
            data_transfer_class="AndroidHttp", data_transfer_config={'url': self.url})
        self.success_started = True
        self.logger.info(f'{self.name}: HTTP request triggered')
        output = self.ue_instance.rpc_client.get_data_transfer_output(ue_id=self.ue_instance.ue_id,
                                                                      data_transfer_id=self.name,
                                                                      raw_output=True)['raw_output']
        self.logger.debug(f'{self.name} output: \n{output}')
        self.is_running_ = False

    def release_data_transfer(self):
        """HTTP data transfer cleanup"""
        self.stop()

    def is_running(self):
        """
        Check if data transfer is running
        :return: boolean
        """
        return self.is_running_

    def stop(self):
        """
        Inherited.
        :return:
        """
        if self.is_running():
            self.ue_instance.rpc_client.stop_data_transfer(ue_id=self.ue_instance.ue_id,
                                                           data_transfer_id=self.name)
        else:
            self.logger.debug(f'Data transfer {self.name} has finished. No need to release again')

    def await_finish(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError

    def check_data_transfer(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError

    def reset_statistics(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError

    def get_average_throughput(self, **kwargs):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError

    def get_datagram_loss(self):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError

    def get_data_transfer_statistics(self, **kwargs):
        """
        Inherited.
        :return:
        """
        raise NotImplementedError
